        if (ನಮೂದು_ಬಿಂದು_ಮೌಲ್ಯ < 0 || (ವಿಧಾನ_ಪ್ರವೇಶ[ನಮೂದು_ಬಿಂದು_ಮೌಲ್ಯ] & 9) != 9) ವೈಫಲ್ಯ_ಮೌಲ್ಯ("public static void ಚಲಾಯಿಸು_2() or main(String[] args) required");
